:root {
  --ink: #170f32;
  --ink-2: #271849;
  --cream: #fff5df;
  --cream-dim: #d9cbe8;
  --teal: #36f0cd;
  --teal-deep: #0c8f8d;
  --gold: #ffd05b;
  --gold-deep: #ff9a3c;
  --coral: #ff6b57;
  --pink: #ff8db0;
  --violet: #6c4bb6;
  --glass: rgba(23, 14, 50, 0.52);
  --glass-line: rgba(255, 245, 223, 0.16);
  --shadow: 0 24px 80px rgba(9, 5, 25, 0.42);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --font-display: "Arial Black", "Avenir Next Condensed", "Franklin Gothic Heavy", "Trebuchet MS", sans-serif;
  --font-body: "Avenir Next", "Segoe UI", "Trebuchet MS", sans-serif;
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: #1a1038;
  color: var(--cream);
  font-family: var(--font-body);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body {
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(120% 90% at 50% 105%, rgba(255, 142, 112, 0.22), transparent 55%),
    #1a1038;
}

#game-canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
  touch-action: none;
}

.sky-grade,
.vignette,
.grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.sky-grade {
  background:
    linear-gradient(180deg, rgba(25, 14, 57, 0.1) 0%, transparent 24%, transparent 66%, rgba(26, 10, 46, 0.16) 100%),
    linear-gradient(90deg, rgba(255, 139, 115, 0.05), transparent 42%, rgba(74, 35, 132, 0.08));
  mix-blend-mode: soft-light;
}

.vignette {
  background:
    radial-gradient(ellipse at 50% 47%, transparent 44%, rgba(12, 5, 30, 0.16) 70%, rgba(10, 4, 25, 0.58) 116%),
    linear-gradient(180deg, rgba(10, 4, 24, 0.22), transparent 16%, transparent 78%, rgba(10, 4, 24, 0.32));
}

.grain {
  opacity: 0.13;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.95' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.55'/%3E%3C/svg%3E");
  background-size: 180px 180px;
}

#hit-flash {
  position: absolute;
  inset: 0;
  z-index: 18;
  pointer-events: none;
  opacity: 0;
  background:
    radial-gradient(ellipse at 50% 52%, rgba(255, 255, 255, 0.65), transparent 20%),
    linear-gradient(180deg, rgba(255, 75, 70, 0.48), rgba(255, 80, 80, 0.14));
  mix-blend-mode: screen;
}

#hit-flash.flash {
  animation: hitFlash 0.52s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes hitFlash {
  0% { opacity: 0; }
  10% { opacity: 1; }
  100% { opacity: 0; }
}

.is-hidden { display: none !important; }

/* ---------- shared type / buttons ---------- */

.eyebrow,
.panel-kicker,
.hud-label,
.control-key,
.side-label,
.best-chip span,
.final-score > span,
.result-grid span {
  font-family: var(--font-body);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: rgba(255, 245, 223, 0.66);
}

.eyebrow-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 12px var(--teal);
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  padding: 0;
  border: 1px solid rgba(255, 245, 223, 0.18);
  border-radius: 50%;
  color: var(--cream);
  background: rgba(25, 14, 53, 0.42);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  cursor: pointer;
  transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease;
}

.icon-btn:hover {
  transform: translateY(-1px);
  background: rgba(48, 28, 88, 0.65);
  border-color: rgba(255, 245, 223, 0.34);
}

.icon-btn:active { transform: scale(0.94); }

.icon-btn svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-btn .icon-off { display: none; }
.icon-btn.muted .icon-on { display: none; }
.icon-btn.muted .icon-off { display: block; }

.primary-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  min-width: 196px;
  height: 62px;
  padding: 0 27px;
  border: 0;
  border-radius: 18px;
  overflow: hidden;
  color: #241433;
  background: linear-gradient(135deg, #ffe37f 0%, var(--gold) 38%, var(--gold-deep) 100%);
  box-shadow:
    0 2px 0 rgba(255, 255, 255, 0.42) inset,
    0 16px 34px rgba(255, 154, 60, 0.28),
    0 0 0 1px rgba(255, 241, 184, 0.48) inset;
  font-family: var(--font-display);
  font-size: 19px;
  letter-spacing: 0.07em;
  cursor: pointer;
  transition: transform 0.16s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.16s ease, filter 0.16s ease;
}

.primary-btn:hover {
  transform: translateY(-2px) scale(1.015);
  filter: brightness(1.05);
  box-shadow:
    0 2px 0 rgba(255, 255, 255, 0.48) inset,
    0 20px 42px rgba(255, 154, 60, 0.38),
    0 0 0 1px rgba(255, 241, 184, 0.55) inset;
}

.primary-btn:active { transform: translateY(1px) scale(0.985); }

.primary-btn svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 0.16s ease;
}

.primary-btn:hover svg { transform: translateX(4px); }

.btn-shine {
  position: absolute;
  top: -40%;
  left: -30%;
  width: 28%;
  height: 180%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.64), transparent);
  transform: rotate(16deg);
  animation: shine 4.4s ease-in-out infinite;
  pointer-events: none;
}

@keyframes shine {
  0%, 56% { left: -35%; opacity: 0; }
  62% { opacity: 0.8; }
  80%, 100% { left: 120%; opacity: 0; }
}

.ghost-btn {
  height: 54px;
  padding: 0 24px;
  border: 1px solid rgba(255, 245, 223, 0.24);
  border-radius: 16px;
  color: var(--cream);
  background: rgba(255, 245, 223, 0.045);
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.ghost-btn:hover {
  background: rgba(255, 245, 223, 0.1);
  border-color: rgba(255, 245, 223, 0.44);
  transform: translateY(-1px);
}

/* ---------- loading ---------- */

.loading {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  background:
    radial-gradient(70% 55% at 50% 45%, rgba(107, 63, 152, 0.46), transparent 70%),
    #1a1038;
  transition: opacity 0.55s ease, visibility 0.55s ease;
}

.loading.done {
  opacity: 0;
  visibility: hidden;
}

.loading-mark {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: clamp(28px, 5vw, 48px);
  letter-spacing: 0.06em;
  color: var(--cream);
}

.loading-wing {
  color: var(--teal);
  font-size: 1.2em;
  line-height: 1;
  transform: rotate(-14deg);
  text-shadow: 0 0 24px var(--teal);
}

.loading-track {
  width: min(260px, 54vw);
  height: 3px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 245, 223, 0.14);
}

.loading-track i {
  display: block;
  width: 42%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, transparent, var(--teal), var(--gold), transparent);
  animation: loadSlide 1.25s ease-in-out infinite;
}

@keyframes loadSlide {
  from { transform: translateX(-120%); }
  to { transform: translateX(340%); }
}

.loading p {
  margin: 0;
  color: rgba(255, 245, 223, 0.46);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

/* ---------- menu ---------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 10;
}

.menu-screen {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding:
    calc(24px + var(--safe-top))
    calc(34px + var(--safe-right))
    calc(22px + var(--safe-bottom))
    calc(34px + var(--safe-left));
  background:
    linear-gradient(90deg, rgba(19, 10, 43, 0.88) 0%, rgba(19, 10, 43, 0.56) 32%, transparent 64%),
    linear-gradient(180deg, rgba(19, 10, 43, 0.38), transparent 28%, transparent 72%, rgba(19, 10, 43, 0.46));
  animation: menuIn 0.8s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes menuIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.menu-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.menu-utility { display: flex; gap: 10px; }

.menu-body {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.16fr) minmax(260px, 0.56fr);
  align-items: center;
  gap: 4vw;
  min-height: 0;
  padding: 1vh 0;
}

.hero-copy {
  align-self: center;
  max-width: 690px;
  padding-left: clamp(0px, 2vw, 26px);
}

.title-lockup { position: relative; }

.title-kicker {
  display: inline-block;
  margin-bottom: 10px;
  color: var(--teal);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  text-shadow: 0 0 22px rgba(54, 240, 205, 0.45);
}

.title-lockup h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(62px, 10.5vw, 150px);
  line-height: 0.78;
  letter-spacing: -0.07em;
  text-transform: uppercase;
  filter: drop-shadow(0 16px 28px rgba(15, 7, 35, 0.34));
}

.title-lockup h1 span {
  display: block;
  background: linear-gradient(180deg, #fff8e8 4%, #ffe7a3 42%, #ffb461 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-stroke: 1px rgba(255, 250, 231, 0.18);
}

.title-lockup h1 .title-wing {
  margin-left: 0.24em;
  background: linear-gradient(180deg, #e8fffb 0%, #5bffe3 42%, #14b7b1 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-stroke: 1px rgba(172, 255, 242, 0.2);
}

.hero-sub {
  margin: 20px 0 27px;
  color: rgba(255, 245, 223, 0.78);
  font-size: clamp(15px, 1.55vw, 21px);
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: 0.01em;
}

.hero-sub em {
  color: var(--gold);
  font-style: normal;
  font-weight: 800;
}

.menu-actions {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
}

.best-chip {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 9px 18px 10px;
  border-left: 1px solid rgba(255, 245, 223, 0.2);
}

.best-chip span { color: rgba(255, 245, 223, 0.48); font-size: 8px; }
.best-chip strong {
  font-family: var(--font-display);
  font-size: 25px;
  line-height: 1;
  letter-spacing: 0.02em;
  color: var(--cream);
}

.control-row {
  display: flex;
  gap: 10px;
  margin-top: 29px;
  max-width: 540px;
}

.control-card {
  position: relative;
  display: grid;
  grid-template-columns: 42px 1fr;
  grid-template-rows: auto auto;
  align-items: center;
  gap: 0 12px;
  flex: 1;
  min-width: 0;
  padding: 13px 15px 13px 13px;
  border: 1px solid rgba(255, 245, 223, 0.12);
  border-radius: 15px;
  background: linear-gradient(135deg, rgba(255, 245, 223, 0.075), rgba(255, 245, 223, 0.022));
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
