  outer.rotation.z = rand(0, Math.PI);
  group.add(outer);
  const core = new THREE.Mesh(anchorCoreGeo, sparkMat);
  group.add(core);
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTexture,
    color: 0xffc65e,
