import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const url = process.argv[2] || 'http://127.0.0.1:3002';
const out = process.argv[3] || '/tmp/opencode/shot.jpg';
const width = Number(process.argv[4] || 1280);
const height = Number(process.argv[5] || 800);
const click = process.argv[6] !== 'no-click';
mkdirSync('/tmp/opencode', { recursive: true });

const browser = await chromium.launch({
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome',
  headless: true,
  args: [
    '--enable-gpu',
    '--ignore-gpu-blocklist',
    '--enable-unsafe-webgpu',
    '--use-angle=swiftshader',
    '--enable-webgl',
  ],
});
const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (error) => { errors.push(`PAGEERROR: ${error.message}`); console.log('PAGEERROR', error.message); });
page.on('console', (message) => {
  if (message.type() === 'error' || message.type() === 'warning') console.log('CONSOLE', message.type(), message.text());
});
page.on('response', (response) => {
  if (response.status() >= 400) console.log('HTTP', response.status(), response.url());
});
await page.goto(url, { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(700);
if (click) {
  const start = page.getByRole('button', { name: 'PLAY', exact: true });
  await start.click({ timeout: 5000 });
  await page.waitForTimeout(Number(process.env.WAIT_AFTER || 1100));
}
await page.screenshot({ path: out, type: out.endsWith('.png') ? 'png' : 'jpeg', quality: out.endsWith('.png') ? undefined : 82 });
const info = await page.evaluate(() => ({
  mode: window.__HOOKWING__?.state?.mode,
  score: window.__HOOKWING__?.state?.score,
  x: window.__HOOKWING__?.bird?.x,
  y: window.__HOOKWING__?.bird?.y,
  gates: window.__HOOKWING__?.gates?.length,
  best: window.__HOOKWING__?.best,
  canvas: [document.querySelector('canvas')?.width, document.querySelector('canvas')?.height],
  loading: Boolean(document.querySelector('#loading')),
}));
console.log(JSON.stringify({ info, errors }, null, 2));
await browser.close();

