import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome',
  headless: false,
  args: [
    '--enable-gpu','--ignore-gpu-blocklist','--enable-unsafe-webgpu',
    '--use-angle=vulkan','--enable-features=Vulkan','--use-vulkan=swiftshader','--use-webgpu-adapter=swiftshader','--disable-vulkan-surface',
    '--disable-background-timer-throttling','--disable-backgrounding-occluded-windows','--disable-renderer-backgrounding',
  ],
});

async function shot(name, width, height, setup, wait = 500) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
  await page.goto('http://127.0.0.1:3002', { waitUntil: 'load' });
  await page.waitForTimeout(600);
  await page.evaluate(setup);
  await page.waitForTimeout(wait);
  await page.screenshot({ path: `/tmp/opencode/${name}.jpg`, type: 'jpeg', quality: 84 });
  const info = await page.evaluate(() => ({
    mode: window.__HOOKWING__.state.mode,
    x: +window.__HOOKWING__.bird.x.toFixed(2),
    y: +window.__HOOKWING__.bird.y.toFixed(2),
    score: window.__HOOKWING__.state.score,
    gates: window.__HOOKWING__.gates.map(g => ({x:+g.x.toFixed(1), gapY:+g.gapY.toFixed(1), gapTop:+g.gapTop.toFixed(1), gapBottom:+g.gapBottom.toFixed(1)})).slice(0,3),
    grapple: Boolean(window.__HOOKWING__.grapple.anchor),
    anchor: window.__HOOKWING__.grapple.anchor ? {used: window.__HOOKWING__.grapple.anchor.used, x: window.__HOOKWING__.grapple.anchor.group.position.x} : null,
  }));
  console.log(name, JSON.stringify(info), errors);
  await page.close();
}

