import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: false, args:['--use-angle=vulkan','--enable-features=Vulkan','--use-vulkan=swiftshader','--disable-vulkan-surface','--disable-backgrounding-occluded-windows'] });
const page = await browser.newPage({ viewport: { width: 960, height: 600 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://127.0.0.1:3002', { waitUntil: 'load' });
await page.waitForTimeout(600);

// pass a gate
await page.evaluate(() => {
  const h = window.__HOOKWING__;
  h.jumpTo(8.6, h.gates[0].gapY);
  h.bird.vy = 0;
});
await page.waitForTimeout(1600);
console.log('pass gate', await page.evaluate(() => ({
  mode: window.__HOOKWING__.state.mode,
  x: +window.__HOOKWING__.bird.x.toFixed(2),
  score: window.__HOOKWING__.state.score,
  gates: window.__HOOKWING__.state.gatesPassed,
  y: +window.__HOOKWING__.bird.y.toFixed(2),
})));

// reset, collect spark
await page.evaluate(() => {
  const h = window.__HOOKWING__;
  h.showMenu(); h.startGame();
  const g = h.gates[0];
  const s = g.sparks[0];
  h.state.startDelay = 0;
  h.bird.x = g.x + s.localX - 0.1;
  h.bird.y = s.mesh.position.y;
  h.bird.vy = 0;
  h.camera.position.x = h.bird.x + 3;
});
await page.waitForTimeout(1200);
console.log('collect spark', await page.evaluate(() => ({
  mode: window.__HOOKWING__.state.mode,
  sparks: window.__HOOKWING__.state.sparks,
  score: window.__HOOKWING__.state.score,
  sparkVisible: window.__HOOKWING__.gates[0]?.sparks[0]?.mesh.visible,
})));

// reset, hit top pipe
await page.evaluate(() => {
  const h = window.__HOOKWING__;
  h.showMenu(); h.startGame();
  const g = h.gates[0];
  h.state.startDelay = 0;
  h.bird.x = g.x;
  h.bird.y = g.gapTop + 0.8;
  h.bird.vy = 0;
});
await page.waitForTimeout(800);
console.log('hit pipe', await page.evaluate(() => ({
  mode: window.__HOOKWING__.state.mode,
  x: +window.__HOOKWING__.bird.x.toFixed(2),
  y: +window.__HOOKWING__.bird.y.toFixed(2),
})));

// pause / resume
await page.evaluate(() => { window.__HOOKWING__.showMenu(); window.__HOOKWING__.startGame(); document.querySelector('#pause-btn').click(); });
console.log('paused', await page.evaluate(() => window.__HOOKWING__.state.mode));
await page.evaluate(() => document.querySelector('#resume-btn').click());
console.log('resumed', await page.evaluate(() => window.__HOOKWING__.state.mode));

await browser.close();

